// routes/feed.js — RSS 2.0 feed generated by scanning the site's own
// content directories (Articles/, Tutorials/, Materials/) at request
// time, so new pages show up automatically without needing a matching
// code change here. Each item's title/description come from the
// page's own <title> and <meta name="description">; the page's file
// modified-time is used for sort order and pubDate.

const express = require('express');
const fs = require('fs');
const path = require('path');
const router = express.Router();

const siteRoot = path.resolve(__dirname, '..', '..');
const CONTENT_DIRS = ['Articles', 'Tutorials', 'Materials'];

function extractTag(html, regex) {
  const m = regex.exec(html);
  return m ? m[1].trim() : '';
}

function decodeEntities(str) {
  return String(str)
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function escapeXml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function collectArticles() {
  const items = [];
  CONTENT_DIRS.forEach(function (dir) {
    const dirPath = path.join(siteRoot, dir);
    let files;
    try {
      files = fs.readdirSync(dirPath);
    } catch (e) {
      return; // directory doesn't exist — skip quietly
    }
    files.forEach(function (file) {
      if (!file.toLowerCase().endsWith('.html')) return;
      // Skip index/listing pages, not individual content pages.
      if (/^(index|articles|tutorials|materials|learning-materials)\.html$/i.test(file)) return;

      const filePath = path.join(dirPath, file);
      let html, stat;
      try {
        html = fs.readFileSync(filePath, 'utf8');
        stat = fs.statSync(filePath);
      } catch (e) {
        return;
      }

      let title = decodeEntities(extractTag(html, /<title[^>]*>([^<]*)<\/title>/i));
      title = title.replace(/\s*-\s*ScottVentures\s*$/i, '').trim();
      if (!title) title = file.replace(/\.html$/i, '');

      let desc = decodeEntities(
        extractTag(html, /<meta\s+name=["']description["']\s+content=["']([^"']*)["']/i) ||
        extractTag(html, /<meta\s+content=["']([^"']*)["']\s+name=["']description["']/i)
      );
      if (!desc) desc = title;

      items.push({
        title: title,
        desc: desc,
        href: dir + '/' + file,
        mtime: stat.mtime
      });
    });
  });

  items.sort(function (a, b) { return b.mtime - a.mtime; });
  return items;
}

router.get('/', (req, res) => {
  const origin = req.protocol + '://' + req.get('host');
  const articles = collectArticles();

  const items = articles.map(function (a) {
    return (
      '  <item>\n' +
      '    <title>' + escapeXml(a.title) + '</title>\n' +
      '    <link>' + origin + '/' + a.href + '</link>\n' +
      '    <guid>' + origin + '/' + a.href + '</guid>\n' +
      '    <description>' + escapeXml(a.desc) + '</description>\n' +
      '    <pubDate>' + a.mtime.toUTCString() + '</pubDate>\n' +
      '  </item>'
    );
  }).join('\n');

  const xml =
    '<?xml version="1.0" encoding="UTF-8"?>\n' +
    '<rss version="2.0">\n' +
    '<channel>\n' +
    '  <title>ScottVentures</title>\n' +
    '  <link>' + origin + '/</link>\n' +
    '  <description>Short, direct explainers on hardware, coding tricks, and hands-on tutorials.</description>\n' +
    items + '\n' +
    '</channel>\n' +
    '</rss>\n';

  res.set('Content-Type', 'application/rss+xml');
  res.send(xml);
});

module.exports = router;
